-- استيراد بيان الجمعيات/المؤسسات/الاتحادات المركزية (988 صف بعد تنظيف التكرار)
-- شغّلي هذا الملف بعد تشغيل 00_wipe_all_organizations_data.sql
-- ملحوظة: كل الصفوف دي 'مركزي' لأن الملف الأصلي بيان الجمعيات المركزية بس -
-- الجمعيات المديرية مش موجودة في هذا الملف ومحتاجة بيان منفصل لو موجود عندك
-- ══════════════════════════════════════════════════════════════════
USE NGO_System;
GO

-- === تأكيد وجود الأعمدة دي قبل الـ INSERT (نفس اللي بيضيفها 26_level_transition_dissolution.sql) ===
IF COL_LENGTH('Organizations','LevelChangeNote') IS NULL
  ALTER TABLE Organizations ADD LevelChangeNote NVARCHAR(500) NULL;

IF COL_LENGTH('Organizations','LevelChangeDate') IS NULL
  ALTER TABLE Organizations ADD LevelChangeDate DATE NULL;

IF COL_LENGTH('Organizations','DissolutionDate') IS NULL
  ALTER TABLE Organizations ADD DissolutionDate DATE NULL;
GO

GO

GO

GO

GO

GO

DECLARE @OrgCount INT = (SELECT COUNT(*) FROM Organizations);
PRINT N'✅ تم استيراد ' + CAST(@OrgCount AS NVARCHAR) + N' جمعية/مؤسسة/اتحاد مركزي بنجاح.';
GO